class Node:
    def __init__(self, x, nxt=None):
        self.x, self.next = x, nxt

def reverse(head):
    prev = None
    while head:
        head.next, prev, head = prev, head, head.next
    return prev

def balanced(s):
    pairs = {')': '(', ']': '[', '}': '{'}
    st = []
    for ch in s:
        if ch in pairs.values():
            st.append(ch)
        elif ch in pairs:
            if not st or st.pop() != pairs[ch]:
                return False
    return not st

from collections import deque
def sliding_max(a, k):
    dq, ans = deque(), []
    for i, x in enumerate(a):
        while dq and a[dq[-1]] <= x:
            dq.pop()
        dq.append(i)
        if dq[0] <= i - k:
            dq.popleft()
        if i >= k - 1:
            ans.append(a[dq[0]])
    return ans

from collections import defaultdict
def group_anagrams(words):
    groups = defaultdict(list)
    for w in words:
        groups[tuple(sorted(w))].append(w)
    return list(groups.values())

import heapq
def k_smallest(a, k):
    return heapq.nsmallest(k, a)

def merge_k(lists):
    pq = [(row[0], i, 0) for i, row in enumerate(lists) if row]
    heapq.heapify(pq)
    while pq:
        val, i, j = heapq.heappop(pq)
        yield val
        if j + 1 < len(lists[i]):
            heapq.heappush(pq, (lists[i][j + 1], i, j + 1))

class Trie:
    def __init__(self):
        self.next = {}
        self.end = False
    def insert(self, w):
        node = self
        for ch in w:
            node = node.next.setdefault(ch, Trie())
        node.end = True
    def search(self, w):
        node = self
        for ch in w:
            node = node.next.get(ch)
            if node is None:
                return False
        return node.end

class DSU:
    def __init__(self, n):
        self.p = list(range(n))
        self.r = [0] * n
    def find(self, x):
        while self.p[x] != x:
            self.p[x] = self.p[self.p[x]]
            x = self.p[x]
        return x
    def union(self, a, b):
        a, b = self.find(a), self.find(b)
        if a == b:
            return False
        if self.r[a] < self.r[b]:
            a, b = b, a
        self.p[b] = a
        self.r[a] += self.r[a] == self.r[b]
        return True

class Fenwick:
    def __init__(self, n):
        self.n = n
        self.t = [0] * (n + 1)
    def add(self, i, v):  # 1-based
        while i <= self.n:
            self.t[i] += v
            i += i & -i
    def sum(self, i):
        s = 0
        while i > 0:
            s += self.t[i]
            i -= i & -i
        return s

PSEUDOCODE split(root, key) -> (L, R):
  if root is None: return (None, None)
  if root.key < key:
    L1, R1 = split(root.right, key)
    root.right = L1; update(root); return (root, R1)
  else:
    L1, R1 = split(root.left, key)
    root.left = R1; update(root); return (L1, root)
